import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Spellbooks, scrolls and reagents","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/spellbooks-scrolls-and-reagents.md","filePath":"en/guide/magic/spellbooks-scrolls-and-reagents.md"}'),r={name:"en/guide/magic/spellbooks-scrolls-and-reagents.md"};function o(l,e,i,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="spellbooks-scrolls-and-reagents" tabindex="-1">Spellbooks, scrolls and reagents <a class="header-anchor" href="#spellbooks-scrolls-and-reagents" aria-label="Permalink to &quot;Spellbooks, scrolls and reagents&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Knowledge should persist, while rare grimoires, scrolls and reagents remain physical resources at risk.</li><li>Scrolls offer consumable tactical access, not permanent learning.</li><li>Personal-book protection, reference benefits and consumption rules remain unresolved.</li></ul><p><a href="/Syrolands-Public/en/game-design/magic/spellbooks-scrolls-and-reagents.html">Full design specification</a></p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Proposed role / boundary</th></tr></thead><tbody><tr><td>Personal knowledge and book</td><td>Learned magical knowledge should stay with the character. The baseline personal book should not normally drop, but its exact replacement/protection mechanism is undecided. This is not general item insurance.</td></tr><tr><td>Rare physical books</td><td>Rare physical grimoires and manuscripts are different: they can carry valuable knowledge, annotations or reference benefits and can be lootable. Better indexing might help you consult an unmemorized pattern; a rare book is not simply a flat Magery bonus.</td></tr><tr><td>Casting scrolls</td><td>Scrolls are physical consumables and generally drop on death. They may provide temporary access or a prepared variant, and could shorten reference for an unmemorized spell. An emergency Dispel scroll illustrates tactical value at consumable cost. Ordinary casting scrolls do not permanently teach; specially designed teaching artifacts remain an open question.</td></tr><tr><td>Reagents</td><td>Reagents remain risky physical resources that generally drop on death. Catalysts, stabilizers and other materials may support patterns and variants, with Alchemy processing and Inscription connections. No recipe, substitution or failure-consumption rule is finalized.</td></tr></tbody></table><p><a href="/Syrolands-Public/en/guide/professions/inscription.html">Inscription</a> · <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Memory</a>.</p>',8)])])}const h=a(r,[["render",o]]);export{m as __pageData,h as default};
